[{"order":1,"type":"heading","text":"Understanding JUnit Lifecycle Callbacks"},{"order":2,"type":"paragraph","text":"JUnit extension model provides powerful lifecycle callback interfaces such as BeforeAllCallback, BeforeEachCallback, AfterEachCallback, and AfterAllCallback. These interfaces allow developers to execute custom logic at specific points in a test execution lifecycle, enabling cross-cutting concerns like database setup, logging, and resource management without cluttering test code."},{"order":3,"type":"subheading","text":"Core Lifecycle Callback Interfaces"},{"order":4,"type":"bullet_point","text":"BeforeAllCallback: Executed before all tests in the current container (test class)."},{"order":5,"type":"bullet_point","text":"BeforeEachCallback: Executed before each individual test method."},{"order":6,"type":"bullet_point","text":"AfterEachCallback: Executed after each individual test method."},{"order":7,"type":"bullet_point","text":"AfterAllCallback: Executed after all tests in the current container."},{"order":8,"type":"subheading","text":"Implementing a Custom Timing Extension"},{"order":9,"type":"paragraph","text":"The following example demonstrates how to implement both BeforeEachCallback and AfterEachCallback to measure and log the execution time of individual test methods."},{"order":10,"type":"code","text":"import org.junit.jupiter.api.extension.BeforeEachCallback;
import org.junit.jupiter.api.extension.AfterEachCallback;
import org.junit.jupiter.api.extension.ExtensionContext;

public class TimingExtension implements BeforeEachCallback, AfterEachCallback {

    private static final String START_TIME_KEY = "start_time";

    @Override
    public void beforeEach(ExtensionContext context) throws Exception {
        long startTime = System.currentTimeMillis();
        getStore(context).put(START_TIME_KEY, startTime);
    }

    @Override
    public void afterEach(ExtensionContext context) throws Exception {
        long startTime = getStore(context).remove(START_TIME_KEY, long.class);
        long duration = System.currentTimeMillis() - startTime;

        String testName = context.getRequiredTestMethod().getName();
        System.out.printf("Method [%s] took %d ms.\n", testName, duration);
    }

    private ExtensionContext.Store getStore(ExtensionContext context) {
        return context.getStore(ExtensionContext.Namespace.create(getClass(), context.getRequiredTestMethod()));
    }
}"},{"order":11,"type":"subheading","text":"Applying the Extension"},{"order":12,"type":"paragraph","text":"To apply the newly created extension to a test class, use the @ExtendWith annotation provided by JUnit Jupiter. Multiple extensions can be chained together depending on requirements."},{"order":13,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import static org.junit.jupiter.api.Assertions.assertTrue;

@ExtendWith(TimingExtension.class)
public class SampleServiceTest {

    @Test
    public void testLongRunningProcess() throws InterruptedException {
        Thread.sleep(500);
        assertTrue(true);
    }
}"},{"order":14,"type":"subheading","text":"Best Practices"},{"order":15,"type":"bullet_point","text":"Always use the ExtensionContext.Store API for state management inside extensions to prevent thread-safety issues during parallel test execution."},{"order":16,"type":"bullet_point","text":"Keep callback logic lightweight to avoid performance degradation across large test suites."}]
